p = "/home/claude/eberle-buero/static/hilfe/verfahrensdokumentation.html"
s = open(p, encoding="utf-8").read()
n = 0
def ers(alt, neu):
    global s, n
    assert s.count(alt) == 1, (s.count(alt), alt[:90])
    s = s.replace(alt, neu); n += 1
def nach(anker, neu):
    ers(anker, anker + neu)

# 3.1 Stammdaten
nach("Spätere Stammdatenänderungen verändern daher bereits erstellte Belege nicht.</p>",
     "\n<p>Änderungen an den Stammdaten von Kunden, Lieferanten und Mitarbeitern sowie an den Einstellungen des Programms werden mit Zeitpunkt und Benutzer im unveränderbaren Protokoll festgehalten (Abschnitt 5.1a). Für zahlungs- und steuerrelevante Felder (Bankverbindung, Umsatzsteuersatz, Zahlungsziel, Skonto, Rabatt, Preisanzeige, Rechnungsformat, Firmenname, Steuernummer und USt-IdNr. des Betriebs) stehen alter und neuer Wert im Eintrag, eine IBAN verkürzt auf Anfang und Ende; bei Namen, Anschriften, Kontaktdaten und Lohnangaben nur die Tatsache der Änderung, weil Protokolleinträge nicht gelöscht werden können (Datenminimierung). Eingaben in Zahlenfeldern, die sich nicht als Zahl lesen lassen, werden nicht gespeichert, sondern gemeldet; Geldbeträge werden kaufmännisch auf den Cent gerundet.</p>")
# 3.2 Angebote
ers("werden als PDF im Projektordner und im Programmarchiv abgelegt und können bis zur Annahme aktualisiert werden. Als empfangene oder versandte Handels- oder Geschäftsbriefe unterliegen versandte Angebote und Auftragsbestätigungen der Aufbewahrungspflicht (Abschnitt 8).</p>",
    "werden als PDF im Projektordner und im Programmarchiv abgelegt und können bis zur Annahme aktualisiert werden. Als empfangene oder versandte Handels- oder Geschäftsbriefe unterliegen versandte Angebote und Auftragsbestätigungen der Aufbewahrungspflicht (Abschnitt 8). Damit die versandte Fassung erhalten bleibt, auch wenn der Beleg danach geändert wird, legt das Programm bei jedem Versand (E-Mail aus dem Programm oder Vermerk „als versendet“) eine eigene, nicht mehr veränderte PDF-Datei im Datenordner unter <i>belege\\Jahr\\versandt</i> ab und hält Zeitpunkt, Weg, Benutzer, Betrag und Prüfsumme (SHA-256) der Datei in der Tabelle der Versandvorgänge und im Protokoll fest. Die Fassungen sind am Beleg abrufbar. Ein versandter Beleg kann nicht mehr gelöscht werden.</p>")
# 3.3 Ausgangsrechnungen
